"""Generate rtl/kwt_gelu_lut.v from models/quant/scales.json."""
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCALES = os.path.join(ROOT, 'models', 'quant', 'scales.json')
OUT = os.path.join(ROOT, 'rtl', 'kwt_gelu_lut.v')

with open(SCALES, 'r', encoding='utf-8') as f:
    doc = json.load(f)
vals = doc['gelu_lut']
assert len(vals) == 256

lines = [
    '`timescale 1ns / 1ps',
    '// AUTO-GENERATED by tools/gen_gelu_lut_verilog.py -- do not edit',
    '// LUT[i] = round(gelu((i-127)*s_hin) / s_h), i = 0..255',
    'module kwt_gelu_lut (',
    '    input  wire [7:0] idx,',
    '    output reg signed [7:0] val',
    ');',
    '    always @(*) begin',
    '        case (idx)',
]
for i, v in enumerate(vals):
    v = int(v)
    if v < 0:
        lines.append("            8'd%-3d: val = -8'sd%d;" % (i, -v))
    else:
        lines.append("            8'd%-3d: val = 8'sd%d;" % (i, v))
lines += [
    "            default: val = 8'sd0;",
    '        endcase',
    '    end',
    'endmodule',
    '',
]
with open(OUT, 'w', encoding='ascii', newline='\n') as f:
    f.write('\n'.join(lines))

print('wrote %s' % OUT)
print('LUT[0]=%d LUT[127]=%d LUT[254]=%d' % (vals[0], vals[127], vals[254]))
